#!/usr/bin/env python3
"""Self-contained site builder for DELED Pathshala redesign.
Run:  python3 build_site.py
Writes all source files, then regenerates the HTML pages.
"""
import base64
import subprocess
import sys

FILES = {
    "style.css": "",
    "index.html": "",
    "app.js": "",
    "404.html": "",
    "deled-notes.html": "",
    "site.webmanifest": "",
    "generate-library.py": "",
    "generate-semesters.py": "",
    "generate-topics.py": "",
}

def main():
    for path, b64 in FILES.items():
        data = base64.b64decode(b64).decode("utf-8")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(data)
        print("wrote", path)
    # regenerate HTML pages from pdf-index.json + templates
    for script in ["generate-library.py", "generate-semesters.py", "generate-topics.py"]:
        print("running", script)
        subprocess.run([sys.executable, script], check=True)
    print("DONE - site fully built")

if __name__ == "__main__":
    main()
